using System;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public static class Program
{
    private const int MinDepth = 4;

    private sealed class TreeNode
    {
        private readonly TreeNode left;
        private readonly TreeNode right;

        public TreeNode(int depth)
        {
            if (depth > 0)
            {
                left = new TreeNode(depth - 1);
                right = new TreeNode(depth - 1);
            }
        }

        public int Check()
        {
            TreeNode l = left;
            return l == null ? 1 : 1 + l.Check() + right.Check();
        }
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        int stretchDepth = n + 1;
        int stretchCheck = TreeCheck(stretchDepth);

        TreeNode longLivedTree = new TreeNode(n);

        var output = new StringBuilder();

        output.Append("stretch tree of depth ")
              .Append(stretchDepth)
              .Append("\t check: ")
              .Append(stretchCheck)
              .Append('\n');

        int processorCount = Environment.ProcessorCount;

        for (int depth = MinDepth; depth <= n; depth += 2)
        {
            long iterations = 1L << (n - depth + MinDepth);
            long check = CheckTrees(depth, iterations, processorCount);

            output.Append(iterations)
                  .Append("\t trees of depth ")
                  .Append(depth)
                  .Append("\t check: ")
                  .Append(check)
                  .Append('\n');
        }

        output.Append("long lived tree of depth ")
              .Append(n)
              .Append("\t check: ")
              .Append(longLivedTree.Check())
              .Append('\n');

        Console.Write(output.ToString());
    }

    private static int TreeCheck(int depth)
    {
        return new TreeNode(depth).Check();
    }

    private static long CheckTrees(int depth, long iterations, int processorCount)
    {
        if (iterations <= 1 || processorCount <= 1)
        {
            long check = 0;
            for (long i = 0; i < iterations; i++)
                check += TreeCheck(depth);
            return check;
        }

        int workers = (int)Math.Min(iterations, processorCount);
        long total = 0;

        Parallel.For(0, workers, worker =>
        {
            long local = 0;
            for (long i = worker; i < iterations; i += workers)
                local += TreeCheck(depth);

            Interlocked.Add(ref total, local);
        });

        return total;
    }
}
