using System;
using System.Threading.Tasks;

class Program
{
    private static int[] Fact = null!;

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        Fact = new int[n + 1];
        Fact[0] = 1;
        for (int i = 1; i <= n; i++)
            Fact[i] = Fact[i - 1] * i;

        int total = Fact[n];

        int desiredChunks = Math.Max(Environment.ProcessorCount * 64, 1);
        if (desiredChunks > total) desiredChunks = total;

        int chunkSize = (total + desiredChunks - 1) / desiredChunks;
        int taskCount = (total + chunkSize - 1) / chunkSize;

        long[] checksums = new long[taskCount];
        int[] maxFlips = new int[taskCount];

        Parallel.For(0, taskCount, task =>
        {
            int start = task * chunkSize;
            int end = start + chunkSize;
            if (end > total) end = total;

            RunTask(n, start, end, out long checksum, out int maxFlip);

            checksums[task] = checksum;
            maxFlips[task] = maxFlip;
        });

        long finalChecksum = 0;
        int finalMax = 0;

        for (int i = 0; i < taskCount; i++)
        {
            finalChecksum += checksums[i];
            if (maxFlips[i] > finalMax)
                finalMax = maxFlips[i];
        }

        Console.WriteLine(finalChecksum);
        Console.WriteLine("Pfannkuchen(" + n + ") = " + finalMax);
    }

    private static void RunTask(int n, int start, int end, out long checksum, out int maxFlip)
    {
        int[] perm = new int[n];
        int[] count = new int[n];
        int[] temp = new int[n];

        FirstPermutation(n, start, perm, count, temp);

        checksum = 0;
        maxFlip = 0;

        int sign = ((start & 1) == 0) ? 1 : -1;

        for (int idx = start; idx < end; idx++)
        {
            int flips = CountFlips(n, perm, temp);

            checksum += sign * flips;
            sign = -sign;

            if (flips > maxFlip)
                maxFlip = flips;

            if (idx + 1 < end)
                NextPermutation(perm, count);
        }
    }

    private static void FirstPermutation(int n, int index, int[] perm, int[] count, int[] temp)
    {
        for (int i = 0; i < n; i++)
            perm[i] = i;

        for (int i = n - 1; i > 0; i--)
        {
            int d = index / Fact[i];
            count[i] = d;
            index %= Fact[i];

            if (d == 0)
                continue;

            for (int j = 0; j <= i; j++)
                temp[j] = perm[j];

            int m = i + 1;
            for (int j = 0; j <= i; j++)
                perm[j] = temp[(j + d) % m];
        }
    }

    private static void NextPermutation(int[] perm, int[] count)
    {
        int first = perm[1];
        perm[1] = perm[0];
        perm[0] = first;

        int i = 1;
        while (++count[i] > i)
        {
            count[i] = 0;
            i++;

            int next = perm[1];
            perm[0] = next;

            for (int j = 1; j < i; j++)
                perm[j] = perm[j + 1];

            perm[i] = first;
            first = next;
        }
    }

    private static int CountFlips(int n, int[] perm, int[] temp)
    {
        int first = perm[0];

        if (first == 0)
            return 0;

        int flips = 1;

        if (perm[first] == 0)
            return flips;

        for (int i = 0; i < n; i++)
            temp[i] = perm[i];

        do
        {
            flips++;

            int lo = 1;
            int hi = first - 1;

            while (lo < hi)
            {
                int t = temp[lo];
                temp[lo] = temp[hi];
                temp[hi] = t;
                lo++;
                hi--;
            }

            int next = temp[first];
            temp[first] = first;
            first = next;
        }
        while (temp[first] != 0);

        return flips;
    }
}
