using System;
using System.IO;
using System.Text;
using System.Runtime.CompilerServices;

class Program
{
    const int IM = 139968;
    const int IA = 3877;
    const int IC = 29573;

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        byte[] alu = Encoding.ASCII.GetBytes(
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
            "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
            "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
            "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
            "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA");

        int[] iubTransition = CreateTransition(
            Encoding.ASCII.GetBytes("acgtBDHKMNRSVWY"),
            new double[]
            {
                0.27, 0.12, 0.12, 0.27,
                0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
                0.02, 0.02, 0.02, 0.02, 0.02
            });

        int[] homoTransition = CreateTransition(
            Encoding.ASCII.GetBytes("acgt"),
            new double[]
            {
                0.3029549426680,
                0.1979883004921,
                0.1975473066391,
                0.3015094502008
            });

        FastWriter writer = new FastWriter();

        writer.Write(Encoding.ASCII.GetBytes(">ONE Homo sapiens alu\n"));
        WriteRepeat(writer, alu, 2 * n);

        writer.Write(Encoding.ASCII.GetBytes(">TWO IUB ambiguity codes\n"));
        int seed = 42;
        seed = WriteRandom(writer, iubTransition, seed, 3 * n);

        writer.Write(Encoding.ASCII.GetBytes(">THREE Homo sapiens frequency\n"));
        WriteRandom(writer, homoTransition, seed, 5 * n);

        writer.Flush();
    }

    static int[] CreateTransition(byte[] symbols, double[] probabilities)
    {
        double[] cumulative = new double[probabilities.Length];
        double sum = 0.0;

        for (int i = 0; i < probabilities.Length; i++)
        {
            sum += probabilities[i];
            cumulative[i] = sum;
        }

        byte[] lookup = new byte[IM];
        int symbolIndex = 0;

        for (int value = 0; value < IM; value++)
        {
            double r = value / (double)IM;

            while (symbolIndex < cumulative.Length - 1 && cumulative[symbolIndex] <= r)
                symbolIndex++;

            lookup[value] = symbols[symbolIndex];
        }

        int[] transition = new int[IM];

        for (int seed = 0; seed < IM; seed++)
        {
            int next = (seed * IA + IC) % IM;
            transition[seed] = (next << 8) | lookup[next];
        }

        return transition;
    }

    static void WriteRepeat(FastWriter writer, byte[] sequence, int length)
    {
        int remaining = length;
        int index = 0;
        int sequenceLength = sequence.Length;

        while (remaining > 0)
        {
            int lineLength = remaining < 60 ? remaining : 60;

            writer.Ensure(lineLength + 1);
            byte[] buffer = writer.Buffer;
            int pos = writer.Position;

            for (int i = 0; i < lineLength; i++)
            {
                buffer[pos + i] = sequence[index++];
                if (index == sequenceLength)
                    index = 0;
            }

            buffer[pos + lineLength] = (byte)'\n';
            writer.Position = pos + lineLength + 1;

            remaining -= lineLength;
        }
    }

    static int WriteRandom(FastWriter writer, int[] transition, int seed, int length)
    {
        int remaining = length;

        while (remaining > 0)
        {
            int lineLength = remaining < 60 ? remaining : 60;

            writer.Ensure(lineLength + 1);
            byte[] buffer = writer.Buffer;
            int pos = writer.Position;

            for (int i = 0; i < lineLength; i++)
            {
                int t = transition[seed];
                buffer[pos + i] = (byte)t;
                seed = t >> 8;
            }

            buffer[pos + lineLength] = (byte)'\n';
            writer.Position = pos + lineLength + 1;

            remaining -= lineLength;
        }

        return seed;
    }

    sealed class FastWriter
    {
        readonly Stream stream;
        public readonly byte[] Buffer;
        public int Position;

        public FastWriter()
        {
            stream = Console.OpenStandardOutput();
            Buffer = new byte[1 << 20];
            Position = 0;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public void Ensure(int count)
        {
            if (Buffer.Length - Position < count)
                Flush();
        }

        public void Write(byte[] data)
        {
            int offset = 0;
            int count = data.Length;

            while (count > 0)
            {
                int space = Buffer.Length - Position;
                if (space == 0)
                {
                    Flush();
                    space = Buffer.Length;
                }

                int n = count < space ? count : space;
                System.Buffer.BlockCopy(data, offset, Buffer, Position, n);
                Position += n;
                offset += n;
                count -= n;
            }
        }

        public void Flush()
        {
            if (Position > 0)
            {
                stream.Write(Buffer, 0, Position);
                Position = 0;
            }
        }
    }
}
