using System;
using System.Globalization;
using System.IO;
using System.Text;

class Program
{
    private static readonly sbyte[] BaseCode = CreateBaseCode();
    private static readonly char[] Alphabet = { 'A', 'C', 'G', 'T' };
    private static readonly byte[] ThreeHeader = { (byte)'T', (byte)'H', (byte)'R', (byte)'E', (byte)'E' };

    private struct Entry
    {
        public string Key;
        public long Count;

        public Entry(string key, long count)
        {
            Key = key;
            Count = count;
        }
    }

    static void Main(string[] args)
    {
        int.Parse(args[0], CultureInfo.InvariantCulture);

        long[] counts1 = new long[4];
        long[] counts2 = new long[16];

        ulong codeGGT = EncodePattern("GGT");
        ulong codeGGTA = EncodePattern("GGTA");
        ulong codeGGTATT = EncodePattern("GGTATT");
        ulong codeGGTATTTTAATT = EncodePattern("GGTATTTTAATT");
        ulong codeGGTATTTTAATTTATAGT = EncodePattern("GGTATTTTAATTTATAGT");

        ulong mask3 = MaskFor(3);
        ulong mask4 = MaskFor(4);
        ulong mask6 = MaskFor(6);
        ulong mask12 = MaskFor(12);
        ulong mask18 = MaskFor(18);

        long countGGT = 0;
        long countGGTA = 0;
        long countGGTATT = 0;
        long countGGTATTTTAATT = 0;
        long countGGTATTTTAATTTATAGT = 0;

        long sequenceLength = 0;
        ulong rolling = 0;

        bool sawHeader = false;
        bool foundThree = false;
        bool inThree = false;
        bool atLineStart = true;
        bool readingHeader = false;
        bool headerMatches = false;
        int headerChars = 0;
        bool stop = false;

        byte[] buffer = new byte[1 << 20];
        Stream input = Console.OpenStandardInput();

        int bytesRead;
        while (!stop && (bytesRead = input.Read(buffer, 0, buffer.Length)) > 0)
        {
            for (int i = 0; i < bytesRead; i++)
            {
                byte b = buffer[i];

                if (readingHeader)
                {
                    if (b == (byte)'\n' || b == (byte)'\r')
                    {
                        bool isThree = headerMatches && headerChars >= 5;

                        if (foundThree && !isThree)
                        {
                            stop = true;
                            break;
                        }

                        inThree = isThree;
                        if (isThree)
                            foundThree = true;

                        readingHeader = false;
                        atLineStart = true;
                        continue;
                    }

                    if (headerChars < 5)
                    {
                        byte ub = b;
                        if (ub >= (byte)'a' && ub <= (byte)'z')
                            ub = (byte)(ub - 32);

                        if (ub != ThreeHeader[headerChars])
                            headerMatches = false;
                    }

                    headerChars++;
                    continue;
                }

                if (atLineStart && b == (byte)'>')
                {
                    sawHeader = true;
                    readingHeader = true;
                    headerMatches = true;
                    headerChars = 0;
                    atLineStart = false;
                    continue;
                }

                if (b == (byte)'\n' || b == (byte)'\r')
                {
                    atLineStart = true;
                    continue;
                }

                if (!sawHeader)
                    inThree = true;

                if (inThree)
                {
                    int baseValue = BaseCode[b];
                    if (baseValue >= 0)
                    {
                        sequenceLength++;
                        rolling = (rolling << 2) | (uint)baseValue;

                        counts1[baseValue]++;

                        if (sequenceLength >= 2)
                            counts2[(int)(rolling & 0xFUL)]++;

                        if (sequenceLength >= 3 && (rolling & mask3) == codeGGT)
                            countGGT++;

                        if (sequenceLength >= 4 && (rolling & mask4) == codeGGTA)
                            countGGTA++;

                        if (sequenceLength >= 6 && (rolling & mask6) == codeGGTATT)
                            countGGTATT++;

                        if (sequenceLength >= 12 && (rolling & mask12) == codeGGTATTTTAATT)
                            countGGTATTTTAATT++;

                        if (sequenceLength >= 18 && (rolling & mask18) == codeGGTATTTTAATTTATAGT)
                            countGGTATTTTAATTTATAGT++;
                    }
                }

                atLineStart = false;
            }
        }

        StringBuilder output = new StringBuilder(1024);

        AppendFrequencies(output, counts1, 1, sequenceLength);
        output.Append('\n');

        AppendFrequencies(output, counts2, 2, sequenceLength - 1);
        output.Append('\n');

        output.Append(countGGT).Append('\t').Append("GGT").Append('\n');
        output.Append(countGGTA).Append('\t').Append("GGTA").Append('\n');
        output.Append(countGGTATT).Append('\t').Append("GGTATT").Append('\n');
        output.Append(countGGTATTTTAATT).Append('\t').Append("GGTATTTTAATT").Append('\n');
        output.Append(countGGTATTTTAATTTATAGT).Append('\t').Append("GGTATTTTAATTTATAGT").Append('\n');

        Console.Write(output.ToString());
    }

    private static void AppendFrequencies(StringBuilder output, long[] counts, int k, long total)
    {
        if (total <= 0)
            return;

        Entry[] entries = new Entry[counts.Length];
        int entryCount = 0;

        for (int i = 0; i < counts.Length; i++)
        {
            if (counts[i] > 0)
                entries[entryCount++] = new Entry(Decode(i, k), counts[i]);
        }

        Array.Sort(entries, 0, entryCount, Comparer);

        for (int i = 0; i < entryCount; i++)
        {
            double percentage = entries[i].Count * 100.0 / total;
            output.Append(entries[i].Key)
                  .Append(' ')
                  .Append(percentage.ToString("F3", CultureInfo.InvariantCulture))
                  .Append('\n');
        }
    }

    private static int Comparer(Entry a, Entry b)
    {
        int countCompare = b.Count.CompareTo(a.Count);
        if (countCompare != 0)
            return countCompare;

        return string.CompareOrdinal(a.Key, b.Key);
    }

    private static string Decode(int code, int length)
    {
        char[] chars = new char[length];

        for (int i = length - 1; i >= 0; i--)
        {
            chars[i] = Alphabet[code & 3];
            code >>= 2;
        }

        return new string(chars);
    }

    private static ulong EncodePattern(string pattern)
    {
        ulong code = 0;

        for (int i = 0; i < pattern.Length; i++)
        {
            code <<= 2;

            switch (pattern[i])
            {
                case 'A':
                case 'a':
                    code |= 0;
                    break;
                case 'C':
                case 'c':
                    code |= 1;
                    break;
                case 'G':
                case 'g':
                    code |= 2;
                    break;
                case 'T':
                case 't':
                    code |= 3;
                    break;
            }
        }

        return code;
    }

    private static ulong MaskFor(int length)
    {
        return (1UL << (2 * length)) - 1UL;
    }

    private static sbyte[] CreateBaseCode()
    {
        sbyte[] map = new sbyte[256];

        for (int i = 0; i < map.Length; i++)
            map[i] = -1;

        map[(byte)'A'] = 0;
        map[(byte)'a'] = 0;
        map[(byte)'C'] = 1;
        map[(byte)'c'] = 1;
        map[(byte)'G'] = 2;
        map[(byte)'g'] = 2;
        map[(byte)'T'] = 3;
        map[(byte)'t'] = 3;

        return map;
    }
}
