using System.Runtime.CompilerServices;

public static class Program
{
    private const int IterationLimit = 50;

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        int bytesPerRow = (n + 7) >> 3;
        byte[] image = new byte[bytesPerRow * n];

        double[] cr = new double[n];
        double nd = n;

        for (int x = 0; x < n; x++)
            cr[x] = (2.0 * x / nd) - 1.5;

        Parallel.For(0, n, y =>
        {
            double ci = (2.0 * y / nd) - 1.0;
            int rowOffset = y * bytesPerRow;
            int x = 0;
            int outIndex = rowOffset;

            while (x + 8 <= n)
            {
                int bits = 0;

                if (IsInside(cr[x], ci)) bits |= 0x80;
                if (IsInside(cr[x + 1], ci)) bits |= 0x40;
                if (IsInside(cr[x + 2], ci)) bits |= 0x20;
                if (IsInside(cr[x + 3], ci)) bits |= 0x10;
                if (IsInside(cr[x + 4], ci)) bits |= 0x08;
                if (IsInside(cr[x + 5], ci)) bits |= 0x04;
                if (IsInside(cr[x + 6], ci)) bits |= 0x02;
                if (IsInside(cr[x + 7], ci)) bits |= 0x01;

                image[outIndex++] = (byte)bits;
                x += 8;
            }

            if (x < n)
            {
                int bits = 0;
                int mask = 0x80;

                while (x < n)
                {
                    if (IsInside(cr[x], ci))
                        bits |= mask;

                    mask >>= 1;
                    x++;
                }

                image[outIndex] = (byte)bits;
            }
        });

        Stream stdout = Console.OpenStandardOutput();
        byte[] header = Encoding.ASCII.GetBytes("P4\n" + n.ToString(CultureInfo.InvariantCulture) + " " + n.ToString(CultureInfo.InvariantCulture) + "\n");

        stdout.Write(header, 0, header.Length);
        stdout.Write(image, 0, image.Length);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static bool IsInside(double cr, double ci)
    {
        double zr = 0.0;
        double zi = 0.0;
        double zr2 = 0.0;
        double zi2 = 0.0;

        for (int i = 0; i < IterationLimit; i++)
        {
            zi = 2.0 * zr * zi + ci;
            zr = zr2 - zi2 + cr;
            zr2 = zr * zr;
            zi2 = zi * zi;

            if (zr2 + zi2 > 4.0)
                return false;
        }

        return true;
    }
}
