using System;
using System.Globalization;
using System.IO;

public static class Program
{
    private const byte LF = (byte)'\n';
    private const byte CR = (byte)'\r';
    private const byte HeaderStart = (byte)'>';

    public static void Main(string[] args)
    {
        _ = int.Parse(args[0], CultureInfo.InvariantCulture);

        byte[] data = ReadAllInput();
        int length = data.Length;
        byte[] complement = CreateComplementMap();

        using Stream output = new BufferedStream(Console.OpenStandardOutput(), 1 << 20);

        int pos = 0;
        while (pos < length)
        {
            while (pos < length && data[pos] != HeaderStart)
                pos++;

            if (pos >= length)
                break;

            int recordStart = pos;

            while (pos < length && data[pos] != LF)
                pos++;

            if (pos < length)
                pos++;

            int sequenceStart = pos;

            while (pos < length && data[pos] != HeaderStart)
                pos++;

            int recordEnd = pos;

            ReverseComplementInPlace(data, sequenceStart, recordEnd, complement);
            output.Write(data, recordStart, recordEnd - recordStart);
        }
    }

    private static byte[] ReadAllInput()
    {
        using Stream input = Console.OpenStandardInput();

        byte[] buffer = new byte[1 << 20];
        int length = 0;

        while (true)
        {
            if (length == buffer.Length)
            {
                int newSize = buffer.Length <= int.MaxValue / 2 ? buffer.Length * 2 : int.MaxValue;
                if (newSize == buffer.Length)
                    throw new OutOfMemoryException();

                Array.Resize(ref buffer, newSize);
            }

            int read = input.Read(buffer, length, buffer.Length - length);
            if (read == 0)
                break;

            length += read;
        }

        if (length != buffer.Length)
            Array.Resize(ref buffer, length);

        return buffer;
    }

    private static void ReverseComplementInPlace(byte[] data, int start, int end, byte[] complement)
    {
        int left = start;
        int right = end - 1;

        while (left < right)
        {
            while (left < right && (data[left] == LF || data[left] == CR))
                left++;

            while (left < right && (data[right] == LF || data[right] == CR))
                right--;

            if (left >= right)
                break;

            byte a = data[left];
            byte b = data[right];

            data[left] = complement[b];
            data[right] = complement[a];

            left++;
            right--;
        }

        if (left == right && data[left] != LF && data[left] != CR)
            data[left] = complement[data[left]];
    }

    private static byte[] CreateComplementMap()
    {
        byte[] map = new byte[256];

        for (int i = 0; i < map.Length; i++)
            map[i] = (byte)i;

        SetPair(map, 'A', 'T');
        SetPair(map, 'C', 'G');
        SetDirected(map, 'U', 'A');

        SetPair(map, 'R', 'Y');
        SetPair(map, 'K', 'M');
        SetPair(map, 'B', 'V');
        SetPair(map, 'D', 'H');

        SetSelf(map, 'S');
        SetSelf(map, 'W');
        SetSelf(map, 'N');

        return map;
    }

    private static void SetPair(byte[] map, char a, char b)
    {
        map[(byte)a] = (byte)b;
        map[(byte)b] = (byte)a;

        char la = char.ToLowerInvariant(a);
        char lb = char.ToLowerInvariant(b);

        map[(byte)la] = (byte)lb;
        map[(byte)lb] = (byte)la;
    }

    private static void SetDirected(byte[] map, char from, char to)
    {
        map[(byte)from] = (byte)to;
        map[(byte)char.ToLowerInvariant(from)] = (byte)char.ToLowerInvariant(to);
    }

    private static void SetSelf(byte[] map, char c)
    {
        map[(byte)c] = (byte)c;

        char lc = char.ToLowerInvariant(c);
        map[(byte)lc] = (byte)lc;
    }
