using System.Threading.Tasks;

public static class Program
{
    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        double[] u = new double[n];
        double[] v = new double[n];
        double[] tmp = new double[n];

        for (int i = 0; i < n; i++)
            u[i] = 1.0;

        for (int i = 0; i < 10; i++)
        {
            MultiplyAtAv(n, u, v, tmp);
            MultiplyAtAv(n, v, u, tmp);
        }

        double vBv = 0.0;
        double vv = 0.0;

        for (int i = 0; i < n; i++)
        {
            vBv += u[i] * v[i];
            vv += v[i] * v[i];
        }

        Console.WriteLine(Math.Sqrt(vBv / vv).ToString("F9", CultureInfo.InvariantCulture));
    }

    private static void MultiplyAtAv(int n, double[] input, double[] output, double[] tmp)
    {
        MultiplyAv(n, input, tmp);
        MultiplyAtv(n, tmp, output);
    }

    private static void MultiplyAv(int n, double[] input, double[] output)
    {
        Parallel.For(0, n, i =>
        {
            double sum = 0.0;
            double denom = (double)(i + 1) * (i + 2) * 0.5;
            double inc = i + 1;

            for (int j = 0; j < n; j++)
            {
                sum += input[j] / denom;
                denom += inc;
                inc += 1.0;
            }

            output[i] = sum;
        });
    }

    private static void MultiplyAtv(int n, double[] input, double[] output)
    {
        Parallel.For(0, n, i =>
        {
            double sum = 0.0;
            double denom = (double)i * (i + 1) * 0.5 + 1.0;
            double inc = i + 2;

            for (int j = 0; j < n; j++)
            {
                sum += input[j] / denom;
                denom += inc;
                inc += 1.0;
            }

            output[i] = sum;
        });
    }
